  (1, true, 6, 1, 'All democracies hold elections. Country X holds elections. What can we conclude?', '[{"id": "a", "label": "All countries that hold elections are free"}, {"id": "b", "label": "Country X may or may not be a democracy"}, {"id": "c", "label": "Country X is definitely a democracy"}, {"id": "d", "label": "Country X is not a democracy"}]'::jsonb, 'b'),
